    static Node parse(String s) {
        ArrayDeque<Node> st = new ArrayDeque<>();
        Node root = null;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') {
                Node nd = new Node();
                if (!st.isEmpty()) st.peek().items.add(nd);
                st.push(nd);
            } else if (c == ']') {
                root = st.pop();
            } else if (c == '-' || Character.isDigit(c)) {
                int j = i;
                while (j + 1 < s.length() && Character.isDigit(s.charAt(j + 1))) j++;
                Node nd = new Node();
                nd.isInt = true;
                nd.val = Long.parseLong(s.substring(i, j + 1));
                st.peek().items.add(nd);
                i = j;
            }
        }
        return root;
    }

